app = FastAPI(title="Copa Mata-Mata | Xadrez Entre Amigos", docs_url=None, redoc_url=None)


def utc(d: Optional[datetime]):
    if d is None:
        return None
    return d.replace(tzinfo=timezone.utc) if d.tzinfo is None else d.astimezone(timezone.utc)


def iso(d):
    return utc(d).isoformat().replace('+00:00', 'Z') if d else None


SPEEDS = ('ultraBullet', 'bullet', 'blitz', 'rapid', 'classical')
SPEED_LABELS = {'ultraBullet': 'UltraBullet', 'bullet': 'Bullet',
                'blitz': 'Blitz', 'rapid': 'Rapid', 'classical': 'Classical'}


def speed_for_clock(minutes, increment):
    """Cálculo oficial: tempo inicial (segundos) + 40 × incremento."""
    seconds = int(minutes) * 60 + int(increment) * 40
    if seconds < 30:
        return 'ultraBullet'
    if seconds < 180:
        return 'bullet'
    if seconds < 480:
        return 'blitz'
    if seconds < 1500:
        return 'rapid'
    return 'classical'


def lichess_ratings(p):
    """Ratings retornados pelo Lichess, sem modificações manuais."""
    try:
        raw = json.loads(p.ratings_json or '{}')
        if isinstance(raw, dict):
            return raw
    except (ValueError, TypeError):
        pass
    if p.ratings_json is None and p.rating_official is not None:
        return {'rapid': {'rating': p.rating_official, 'prov': bool(p.provisional)}}
    return {}


def manual_ratings(p):
    try:
        raw = json.loads(p.manual_ratings_json or '{}')
        if isinstance(raw, dict):
            return {key: val for key, val in raw.items()
                    if key in SPEEDS and isinstance(val, int) and
                    not isinstance(val, bool) and 400 <= val <= 3500}
    except (ValueError, TypeError):
        pass
    return {}


def stored_ratings(p):
    """No pareamento, um rating manual tem prioridade até ser retirado no painel."""
    combined = lichess_ratings(p).copy()
    for speed, value in manual_ratings(p).items():
        combined[speed] = {'rating': value, 'prov': False, 'source': 'manual'}
    return combined


def effective_rating(p, speed):
    entry = stored_ratings(p).get(speed) or {}
    val = entry.get('rating')
    return val if isinstance(val, int) and not isinstance(val, bool) and val > 0 else None


def pairing_rating(p, speed):
    """Tenta modalidade exata; usa proxy de modalidade vizinha apenas internamente."""
    exact = effective_rating(p, speed)
    if exact is not None:
        return exact
    rank = SPEEDS.index(speed)
    for alternative in sorted((x for x in SPEEDS if x != speed), key=lambda x: abs(SPEEDS.index(x) - rank)):
        fallback = effective_rating(p, alternative)
        if fallback is not None:
            return fallback
    return 1500


def ratings_from_lichess(profile):
    perfs = profile.get('perfs') or {}
    result = {}
    for speed in SPEEDS:
        item = perfs.get(speed) or {}
        val = item.get('rating')
        games = item.get('games')
        if isinstance(val, int) and not isinstance(val, bool) and 400 <= val <= 3500 and (games is None or games > 0):
            result[speed] = {'rating': val, 'prov': bool(item.get('prov', False)),
                             'games': games if isinstance(games, int) else None}
    return result


def pdata(p, t=None, include_private=False):
    # Público recebe só o rating da categoria atual, nunca as outras modalidades
    # ou o rating auxiliar privado usado no sorteio de pares.
    result = {'id': p.id, 'name': p.name, 'nick': p.nick,
              'disqualified': bool(p.disqualified_at), 'disqualified_round': p.disqualified_round}
    if include_private:
        result['ratings_json'] = p.ratings_json
        result['manual_ratings_json'] = p.manual_ratings_json
        if p.disqualified_at:
            result['disqualified_at'] = iso(p.disqualified_at)
            result['disqualification_reason'] = p.disqualification_reason
    if t is not None:
        speed = speed_for_clock(t.minutes, t.increment)
        selected = stored_ratings(p).get(speed) or {}
        result['rating'] = effective_rating(p, speed)
        result['provisional'] = bool(selected.get('prov', False))
    return result


def mdata(m):
    return {"id": m.id, "round": m.round_no, "order": m.sort_order,
            "p1": m.player1_id, "p2": m.player2_id, "winner": m.winner_id,
            "status": m.status, "white_id": m.white_id, "game_url": m.game_url, "source": m.result_source,
            "notes": m.notes}


def tournament_settings(t):
    return {
        'title': t.title,
        'description': t.description,
        'prize': t.prize,
        'minutes': t.minutes,
        'increment': t.increment,
        'round_days': t.round_days,
        'contact_day': t.contact_day,
        'wo_minutes': t.wo_minutes,
        'tiebreak_minutes': t.tiebreak_minutes,
        'tiebreak_increment': t.tiebreak_increment,
        'regulation_sections': regulation_sections(t),
    }


def game_data(g):
    return {
        'id': g.id, 'match_id': g.match_id, 'outcome': g.outcome,
        'game_url': g.game_url, 'source': g.result_source, 'created_at': iso(g.created_at),
    }


def record_game(db, match, outcome, link, source):
    # Preserva cada empate e sua partida de desempate no histórico.
    # Evita duplicar uma mesma partida quando o administrador confirma novamente.
    existing = None
    if link:
        existing = db.scalar(select(MatchGame).where(
            MatchGame.match_id == match.id, MatchGame.game_url == link))
    elif outcome != 'draw':
        existing = db.scalar(select(MatchGame).where(
            MatchGame.match_id == match.id, MatchGame.game_url.is_(None),
            MatchGame.outcome != 'draw').order_by(MatchGame.id.desc()))
    if existing:
        existing.outcome = outcome
        existing.result_source = source
    else:
        db.add(MatchGame(match_id=match.id, outcome=outcome, game_url=link or None,
                         result_source=source))


def status_data(db, include_private=False):
    t = db.get(Tournament, 1)
    players = db.scalars(select(Player).order_by(Player.created_at, Player.id)).all()
    matches = db.scalars(select(Match).order_by(Match.round_no, Match.sort_order)).all()
    return {
        "status": t.status, "round": t.current_round, "started": iso(t.round_started),
        "deadline": iso(t.deadline), "champion_id": t.champion_id,
        "players": [pdata(p, t, include_private=include_private) for p in players], "matches": [mdata(m) for m in matches],
        "games": [game_data(g) for g in db.scalars(select(MatchGame).order_by(MatchGame.id)).all()],
        "admin_enabled": bool(ADMIN_PASSWORD),
        "settings": tournament_settings(t),
        "viewing_archive": False,
    }


def fail(status, message):
    raise HTTPException(status_code=status, detail=message)


def is_admin(req: Request):
    cookie = req.cookies.get("xadrez_admin")
    if not cookie or not ADMIN_PASSWORD:
        return False
    try:
        val = AUTH.loads(cookie, max_age=12 * 3600)
        fingerprint = hashlib.sha256(ADMIN_PASSWORD.encode()).hexdigest()
        return hmac.compare_digest(val, fingerprint)
    except (BadSignature, SignatureExpired):
        return False


def require_admin(req: Request):
    if not is_admin(req):
        fail(401, "Entre no painel com a senha de administrador.")
    # Cookie de sessão SameSite=Strict e cabeçalho JSON obrigatório nas rotas mutáveis.


def lichess_status():
    """Diagnóstico interno, sem expor nomes nem dados de outros jogadores."""
    with LICHESS_LOCK:
        return {
            'last_status': lichess_last_status,
            'cooldown_seconds': max(0, int(lichess_cooldown_until - time.monotonic() + 0.999)),
            'rate_limited': lichess_last_status == 429,
        }


def lichess_get(url, **kwargs):
    """Uma solicitação por vez, com recuo progressivo após HTTP 429."""
    global lichess_cooldown_until, lichess_last_status, lichess_429_streak
    with LICHESS_LOCK:
        if time.monotonic() < lichess_cooldown_until:
            return None
        try:
            response = HTTP.get(url, **kwargs)
        except requests.RequestException as error:
            lichess_last_status = 'network'
            logging.warning('Falha de rede na consulta ao Lichess: %s.', type(error).__name__)
            return None
        lichess_last_status = response.status_code
        if response.status_code == 429:
            lichess_429_streak = min(lichess_429_streak + 1, 6)
            retry_after = response.headers.get('Retry-After', '0')
            try:
                retry_seconds = max(0, int(retry_after))
            except (ValueError, TypeError):
                retry_seconds = 0
            cooldown = min(3600, max(65, retry_seconds, 65 * (2 ** (lichess_429_streak - 1))))
            lichess_cooldown_until = time.monotonic() + cooldown
            logging.warning('Lichess limitou o acesso com HTTP 429. Próxima tentativa em %s segundos.', cooldown)
        elif response.status_code == 200:
            lichess_429_streak = 0
            lichess_cooldown_until = 0
        return response


def get_public_user(nick: str):
    """None se a API falhar; 404 confirmado indica usuário não encontrado."""
    response = lichess_get(f"https://lichess.org/api/user/{nick}", timeout=(3, 5),
                           headers={'Accept': 'application/json'})
    if response is None:
        return None
    if response.status_code == 404:
        fail(400, "Esse usuário não existe no Lichess. Confira o nick.")
    if response.status_code != 200:
        logging.warning('Consulta pública ao Lichess retornou HTTP %s.', response.status_code)
        return None
    try:
        data = response.json()
    except ValueError:
        logging.warning('O Lichess retornou dados inválidos em vez do perfil JSON.')
        return None
    return data if isinstance(data, dict) and data.get('id') else None


def apply_lichess_ratings(player, profile, tournament, origin='server'):
    """Atualiza somente dados oficiais; não apaga os ajustes manuais."""
    perfs = ratings_from_lichess(profile)
    player.ratings_json = json.dumps(perfs, ensure_ascii=False)
    player.verified = 1
    player.ratings_origin = origin
    player.ratings_synced_at = datetime.now(timezone.utc)
    player.ratings_attempted_at = player.ratings_synced_at
    player.ratings_error = None
    player.rating_official = (perfs.get('rapid') or {}).get('rating')
    speed = speed_for_clock(tournament.minutes, tournament.increment)
    entry = stored_ratings(player).get(speed) or {}
    player.rating = entry.get('rating') or 1500
    player.provisional = int(bool(entry.get('prov', False)))


def retry_one_pending_rating():
    """Em visitas ao site, consulta um pendente elegível e segue a fila sem repetir o mesmo nick."""
    try:
        if lichess_status()['cooldown_seconds']:
            return
        now = datetime.now(timezone.utc)
        cutoff = now - RATINGS_PLAYER_RETRY_INTERVAL
        with Session.begin() as db:
            player = db.scalar(select(Player).where(
                Player.verified == 0,
                (Player.ratings_attempted_at.is_(None) | (Player.ratings_attempted_at <= cutoff))
            ).order_by(Player.ratings_attempted_at.asc().nullsfirst(), Player.id))
            if player is None:
                return
            player_id, nick = player.id, player.nick
            player.ratings_attempted_at = now
        try:
            profile = get_public_user(nick)
        except HTTPException as error:
            if error.status_code == 400:
                with Session.begin() as db:
                    player = db.get(Player, player_id)
                    if player and player.verified == 0 and player.nick_key == nick.casefold():
                        player.verified = -1
                        player.ratings_error = 'Nick não encontrado'
            return
        if profile is None:
            diagnostic = lichess_status()
            label = ('Acesso limitado (429)' if diagnostic['rate_limited']
                     else 'Falha de conexão' if diagnostic['last_status'] == 'network'
                     else 'Lichess temporariamente indisponível')
            with Session.begin() as db:
                player = db.get(Player, player_id)
                if player and player.verified == 0 and player.nick_key == nick.casefold():
                    player.ratings_error = label
            return
        with Session.begin() as db:
            player = db.get(Player, player_id)
            if player and player.verified == 0 and player.nick_key == nick.casefold():
                apply_lichess_ratings(player, profile, db.get(Tournament, 1))
    except Exception:
        logging.exception('Falha ao tentar atualizar rating pendente.')


def schedule_pending_rating_sync(background_tasks: BackgroundTasks):
    global ratings_retry_after
    with RATINGS_RETRY_LOCK:
        now = time.monotonic()
        if now < ratings_retry_after:
            return
        ratings_retry_after = now + RATINGS_RETRY_INTERVAL
    background_tasks.add_task(retry_one_pending_rating)


def choose_pairs(players: list[Player], previous_byes: dict[int, int], rng: random.Random, speed: str = 'rapid'):
    """Sorteia folgas e pares com preferência estatística por rating próximo."""
    n = len(players)
    if n < 2:
        return [], []
    lower = 2 ** (n.bit_length() - 1)
    byes_number = 0 if n == lower else 2 * lower - n
    candidates = players[:]
    rng.shuffle(candidates)
    # Evita, sempre que possível, que a mesma pessoa receba duas folgas.
    candidates.sort(key=lambda p: previous_byes.get(p.id, 0))
    bye = candidates[:byes_number]
    waiting = candidates[byes_number:]
    waiting.sort(key=lambda p: (pairing_rating(p, speed), rng.random()))
    pairs = []
    # Dividir por blocos de rating e sortear entre pareamentos próximos do ótimo.
    # Evita o efeito dominó do sorteio guloso, que pode deixar os dois últimos
    # participantes com uma diferença de rating desproporcional.
    for start in range(0, len(waiting), 4):
        group = waiting[start:start + 4]
        if len(group) == 2:
            chosen = [(group[0], group[1])]
        else:
            matchings = [
                [(group[0], group[1]), (group[2], group[3])],
                [(group[0], group[2]), (group[1], group[3])],
                [(group[0], group[3]), (group[1], group[2])],
            ]
            costs = [sum(abs(pairing_rating(a, speed)-pairing_rating(b, speed)) for a,b in matching) for matching in matchings]
            minimum = min(costs)
            weights = [math.exp(-(cost-minimum)/100) for cost in costs]
            chosen = rng.choices(matchings, weights=weights, k=1)[0]
        for a, b in chosen:
            pairs.append((a,b) if rng.random()<0.5 else (b,a))
    rng.shuffle(pairs)
    rng.shuffle(bye)
    return pairs, bye


def preview_bracket(players, tournament):
    """Prévia informativa: apenas pares completos e, se ímpar, um aguardando.

    Não cria folgas, não classifica ninguém e não persiste confrontos.
    Ordena pelo rating correspondente ao ritmo e busca a menor diferença
    total entre adversários. Os confrontos são oficiais somente após
    o organizador iniciar o torneio.
    """
    n = len(players)
    if not n:
        return {'matches': [], 'pairs': [], 'waiting': None,
                'first_round_matches': 0}

    speed = speed_for_clock(tournament.minutes, tournament.increment)
    ordered = sorted(players, key=lambda p: (pairing_rating(p, speed), p.id))

    waiting = None
    if n % 2:
        # Em uma lista ordenada por força, o menor custo de pareamento
        # é obtido com vizinhos. Escolhe a única espera que minimiza
        # a diferença total entre todos os pares formados.
        def pairing_cost(skip_index):
            remaining = ordered[:skip_index] + ordered[skip_index + 1:]
            return sum(abs(pairing_rating(remaining[i], speed) -
                           pairing_rating(remaining[i + 1], speed))
                       for i in range(0, len(remaining), 2))
        waiting_index = min(range(n), key=lambda idx: (pairing_cost(idx), -idx))
        waiting = ordered.pop(waiting_index).id

    matches = [
        {'p1': ordered[i].id, 'p2': ordered[i + 1].id,
         'status': 'pending', 'order': i // 2 + 1}
        for i in range(0, len(ordered), 2)
    ]
    return {
        'matches': matches,
        'pairs': [[match['p1'], match['p2']] for match in matches],
        'waiting': waiting,
        'first_round_matches': len(matches),
    }


def bye_counts(db):
    counts = defaultdict(int)
    for m in db.scalars(select(Match).where(Match.status == "bye")):
        counts[m.player1_id] += 1
    return counts


def color_balance(db):
    """Saldo de cores realmente registradas em confrontos anteriores.
    Não conta folgas ou W.O. e não inventa cores em jogos antigos.
    Empates e desempates alternam as cores a cada partida."""
    balance = defaultdict(int)
    matches = db.scalars(select(Match).where(
        Match.white_id.is_not(None), Match.player2_id.is_not(None),
        Match.status.in_(('complete', 'draw_pending'))).order_by(Match.round_no, Match.id)).all()
    games_by_match = defaultdict(list)
    for game in db.scalars(select(MatchGame).order_by(MatchGame.created_at, MatchGame.id)).all():
        games_by_match[game.match_id].append(game)
    for match in matches:
        games = games_by_match.get(match.id, [])
        count = len(games) or 1
        black_id = match.player2_id if match.white_id == match.player1_id else match.player1_id
        # A primeira partida tem a cor sorteada; cada desempate inverte.
        for i in range(count):
            white_id, dark_id = (match.white_id, black_id) if i % 2 == 0 else (black_id, match.white_id)
            balance[white_id] += 1
            balance[dark_id] -= 1
    return balance


def balanced_colors(p1, p2, balances, rng):
    """Escolhe a orientação que minimiza os desvios combinados de cores.
    Caso o custo seja igual, realiza sorteio justo sem considerar rating."""
    options = [(p1.id, p2.id), (p2.id, p1.id)]
    costs = [abs(balances[white]+1) + abs(balances[black]-1)
             for white, black in options]
    best = min(costs)
    choices = [i for i, cost in enumerate(costs) if cost == best]
    selected = rng.choice(choices)
    return options[selected][0]


def add_round(db, t, advancing: list[Player]):
    """A chave oficial converge sempre para a final, sem abrir caminhos paralelos.

    Na primeira rodada: sorteia pares próximos em rating e distribui folgas.
    Nas seguintes: cada posição recebe apenas os vencedores das duas
    posições adjacentes da rodada anterior (1+2, 3+4, ...).
    """
    if len(advancing) <= 1:
        t.status = 'finished'
        t.champion_id = advancing[0].id if advancing else None
        t.round_started = None
        t.deadline = None
        return

    rng = random.SystemRandom()
    balances = color_balance(db)
    next_round_number = t.current_round + 1
    scheduled = []
    if t.current_round == 0:
        # Durante as inscrições não há classificados por folga. O início
        # oficial usa todos os inscritos em confrontos (n/2), sem promoção
        # antecipada. Para números não-potência-de-2, folgas só poderão
        # surgir nas rodadas seguintes, após autorização do organizador.
        if len(advancing) % 2:
            raise ValueError('A primeira rodada exige número par de inscritos.')
        ids = {p.id: p for p in advancing}
        preview = preview_bracket(advancing, t)
        scheduled = [('pair', ids[a], ids[b]) for a, b in preview['pairs']]
        rng.shuffle(scheduled)
        round_slots = list(enumerate(scheduled, 1))
    else:
        previous = db.scalars(select(Match).where(
            Match.round_no == t.current_round).order_by(Match.sort_order)).all()
        by_position = {m.sort_order: m for m in previous}
        first_count = db.scalar(select(func.count()).select_from(Match).where(
            Match.round_no == 1))
        expected_slots = math.ceil(first_count / (2 ** t.current_round))
        if expected_slots < 1:
            raise ValueError('A chave já chegou à sua última fase.')
        round_slots = []
        for i in range(1, expected_slots + 1):
            pair = [by_position.get(2 * i - 1), by_position.get(2 * i)]
            winners = []
            for match in pair:
                if not match or not match.winner_id:
                    continue
                player = db.get(Player, match.winner_id)
                if player and not player.disqualified_at:
                    winners.append(player)
            if len(winners) == 2:
                round_slots.append((i, ('pair', winners[0], winners[1])))
            elif len(winners) == 1:
                round_slots.append((i, ('bye', winners[0], None)))
            # Se ambos os lados foram eliminados, mantém a posição vazia,
            # preservando os índices das outras ramificações.

    t.current_round = next_round_number
    t.round_started = datetime.now(timezone.utc)
    t.deadline = t.round_started + timedelta(days=t.round_days)
    for position, (kind, p1, p2) in round_slots:
        if kind == 'bye':
            db.add(Match(
                round_no=t.current_round, sort_order=position,
                player1_id=p1.id, player2_id=None, winner_id=p1.id,
                status='bye', result_source='automatic'))
            continue
        white = balanced_colors(p1, p2, balances, rng)
        db.add(Match(
            round_no=t.current_round, sort_order=position, player1_id=p1.id,
            player2_id=p2.id, white_id=white, status='pending'))
        black = p2.id if white == p1.id else p1.id
        balances[white] += 1
        balances[black] -= 1


class Signup(BaseModel):
    name: str = Field(min_length=2, max_length=70)
    nick: str = Field(min_length=2, max_length=30)
    agreed_to_rules: bool = False
    @field_validator('name')
    @classmethod
    def strip_name(cls, v):
        v = ' '.join(v.split())
        if len(v) < 2 or not any(ch.isalpha() for ch in v):
            raise ValueError('Informe um nome válido.')
        return v

    @field_validator('nick')
    @classmethod
    def validate_nick(cls, v):
        v = v.strip().lstrip('@')
        if not USERNAME_RE.fullmatch(v):
            raise ValueError('Nick inválido para o Lichess.')
        return v


