class DeleteArchivedTournamentIn(BaseModel):
    confirmation: str = Field(min_length=7, max_length=7)


@app.delete('/api/admin/tournaments/archives/{archive_id}')
def delete_archived_tournament(archive_id: int, data: DeleteArchivedTournamentIn, request: Request):
    """Exclui somente o snapshot de uma edição arquivada.

    Nunca exclui o torneio ativo, seus inscritos, partidas nem resultados.
    Os participantes copiados para outras edições permanecem registrados.
    """
    require_admin(request)
    if archive_id < 1:
        fail(400, 'Não é permitido excluir a edição atual.')
    if data.confirmation != 'EXCLUIR':
        fail(400, 'Digite EXCLUIR para confirmar a remoção definitiva.')
    with Session.begin() as db:
        archive = db.get(TournamentArchive, archive_id)
        if archive is None:
            fail(404, 'A edição arquivada não foi encontrada ou já foi excluída.')
        title = archive.title
        db.delete(archive)
    return {
        'message': 'Edição arquivada excluída definitivamente.',
        'deleted_id': archive_id, 'deleted_title': title,
    }


class ManualRatingsIn(BaseModel):
    classical: Optional[int] = Field(default=None, ge=400, le=3500)
    rapid: Optional[int] = Field(default=None, ge=400, le=3500)
    blitz: Optional[int] = Field(default=None, ge=400, le=3500)


def admin_rating_data(p):
    official = lichess_ratings(p)
    manual = manual_ratings(p)
    data = {}
    for category in ('classical', 'rapid', 'blitz'):
        source = 'manual' if category in manual else ('lichess' if category in official else 'none')
        item = stored_ratings(p).get(category) or {}
        data[category] = {
            'rating': item.get('rating'), 'source': source,
            'provisional': bool(item.get('prov', False))
        }
    return {
        'id': p.id, 'name': p.name, 'nick': p.nick, 'verified': p.verified,
        'synced_at': iso(p.ratings_synced_at),
        'attempted_at': iso(p.ratings_attempted_at),
        'error': p.ratings_error,
        'origin': p.ratings_origin,
        'ratings': data, 'manual': manual
    }



class PlayerIdentityIn(BaseModel):
    name: str = Field(min_length=2, max_length=70)
    nick: str = Field(min_length=2, max_length=30)

    @field_validator('name')
    @classmethod
    def normalize_player_name(cls, value):
        value = ' '.join(value.split())
        if len(value) < 2 or not any(ch.isalpha() for ch in value):
            raise ValueError('Informe um nome válido.')
        return value

    @field_validator('nick')
    @classmethod
    def normalize_player_nick(cls, value):
        value = value.strip().lstrip('@')
        if not USERNAME_RE.fullmatch(value):
            raise ValueError('Nick inválido para o Lichess.')
        return value


@app.put('/api/admin/players/{player_id}/identity')
def update_player_identity(player_id: int, data: PlayerIdentityIn, request: Request):
    """Corrige o cadastro mantendo IDs, confrontos, partidas e aceite intactos."""
    require_admin(request)
    try:
        with Session.begin() as db:
            player = db.get(Player, player_id)
            if not player:
                fail(404, 'Inscrito não encontrado nesta edição.')
            key = data.nick.casefold()
            other = db.scalar(select(Player.id).where(
                Player.nick_key == key, Player.id != player_id))
            if other:
                fail(409, 'Este nick já pertence a outro inscrito do torneio.')
            nick_changed = player.nick_key != key
            player.name = data.name
            player.nick = data.nick
            player.nick_key = key
            if nick_changed:
                # Nunca atribuir ao novo usuário ratings de uma conta antiga.
                player.ratings_json = None
                player.manual_ratings_json = None
                player.ratings_synced_at = None
                player.ratings_attempted_at = None
                player.ratings_error = None
                player.ratings_origin = None
                player.rating_official = None
                player.rating_reported = 1500
                player.rating = 1500
                player.provisional = 0
                player.verified = 0
            db.flush()
    except IntegrityError:
        fail(409, 'Este nick já está inscrito no torneio.')
    return {
        'message': ('Nome e nick atualizados. Os ratings anteriores foram limpos; '
                    'o sistema tentará consultar o novo usuário no Lichess.'
                    if nick_changed else 'Dados do participante atualizados.'),
        'nick_changed': nick_changed,
    }


