@app.put('/api/admin/players/{player_id}/ratings')
def set_manual_ratings(player_id: int, data: ManualRatingsIn, request: Request):
    """Campos vazios retiram o ajuste manual, recuperando o rating oficial."""
    require_admin(request)
    with Session.begin() as db:
        player = db.get(Player, player_id)
        if not player:
            fail(404, 'Jogador não encontrado nesta edição.')
        manual = manual_ratings(player)
        for category in ('classical', 'rapid', 'blitz'):
            value = getattr(data, category)
            if value is None:
                manual.pop(category, None)
            else:
                manual[category] = value
        player.manual_ratings_json = json.dumps(manual) if manual else None
        t = db.get(Tournament, 1)
        selected = stored_ratings(player).get(speed_for_clock(t.minutes, t.increment)) or {}
        player.rating = selected.get('rating') or 1500
        player.provisional = int(bool(selected.get('prov', False)))
    return {'message': 'Ratings manuais salvos. Valores vazios voltam a usar o Lichess, quando disponível.'}



class AdminBrowserLichessIn(BaseModel):
    nick: str = Field(min_length=2, max_length=30)
    perfs: dict[str, dict] = Field(default_factory=dict)


@app.post('/api/admin/players/{player_id}/browser-ratings')
def accept_admin_browser_ratings(player_id: int, data: AdminBrowserLichessIn, request: Request):
    """Fallback iniciado pelo navegador do organizador, não verificado pelo servidor.
    Dados recebidos por um administrador autenticado são etiquetados pela origem
    e não podem substituir ajustes manuais existentes."""
    require_admin(request)
    if not USERNAME_RE.fullmatch(data.nick):
        fail(400, 'Nick enviado é inválido.')
    with Session.begin() as db:
        player = db.get(Player, player_id)
        if not player:
            fail(404, 'Inscrito não encontrado.')
        if player.nick_key != data.nick.casefold():
            fail(409, 'O nick mudou durante a consulta. Tente novamente.')
        validated = ratings_from_lichess({'perfs': data.perfs})
        # Guarda somente as categorias padrão e os números aceitos pelo modelo.
        clean_profile = {'perfs': {key: {
            'rating': val['rating'], 'prov': val.get('prov', False),
            'games': val.get('games')
        } for key, val in validated.items()}}
        apply_lichess_ratings(player, clean_profile, db.get(Tournament, 1),
                              origin='admin_browser')
    return {'message': 'Ratings obtidos pelo seu navegador e salvos. Origem identificada no painel.'}


@app.post('/api/admin/players/{player_id}/refresh-ratings')
def refresh_player_lichess_rating(player_id: int, request: Request):
    """O administrador pode tentar consultar novamente sem remover a inscrição."""
    require_admin(request)
    with Session() as db:
        player = db.get(Player, player_id)
        if player is None:
            fail(404, 'Jogador não encontrado nesta edição.')
        nick = player.nick
    try:
        profile = get_public_user(nick)
    except HTTPException as exc:
        if exc.status_code != 400:
            raise
        with Session.begin() as db:
            player = db.get(Player, player_id)
            if player and player.verified != 1 and player.nick_key == nick.casefold():
                player.verified = -1
        return {'message': 'O Lichess informou que esse nick não existe. Confira o cadastro.',
                'not_found': True}
    if profile is None:
        status = lichess_status()
        reason = ('O Lichess limitou as consultas deste servidor (HTTP 429).' if status['rate_limited']
                  else 'O Lichess não respondeu ao servidor.')
        with Session.begin() as db:
            player = db.get(Player, player_id)
            if player and player.nick_key == nick.casefold():
                player.ratings_attempted_at = datetime.now(timezone.utc)
                player.ratings_error = 'Acesso limitado (429)' if status['rate_limited'] else 'Falha temporária'
        return {
            'message': reason + ' Tentaremos pelo seu navegador. A inscrição continuará válida.',
            'pending': True,
            'rate_limited': status['rate_limited'],
            'retry_seconds': status['cooldown_seconds'],
        }
    with Session.begin() as db:
        player = db.get(Player, player_id)
        if player is None:
            fail(404, 'Jogador não encontrado nesta edição.')
        if player.nick_key != nick.casefold():
            fail(409, 'O nick foi alterado durante a consulta. Tente novamente com o novo nick.')
        player.ratings_attempted_at = datetime.now(timezone.utc)
        apply_lichess_ratings(player, profile, db.get(Tournament, 1))
    return {'message': 'Ratings do Lichess atualizados. Ajustes manuais foram mantidos.',
            'pending': False}


@app.get('/api/admin/importable-players')
def list_importable_players(request: Request):
    require_admin(request)
    with Session() as db:
        t = db.get(Tournament, 1)
        if t.status != 'registration':
            return {'available': False, 'editions': [], 'players': [],
                    'message': 'A transferência só é permitida com inscrições abertas.'}
        existing = {p.nick_key for p in db.scalars(select(Player)).all()}
        archives = db.scalars(select(TournamentArchive).order_by(TournamentArchive.id.desc())).all()
        editions = []
        choices = []
        for archive in archives:
            snapshot = json.loads(archive.snapshot)
            edition = {'id': archive.id, 'title': archive.title, 'count': len(snapshot.get('players', []))}
            editions.append(edition)
            seen = set()
            for item in snapshot.get('players', []):
                nick = str(item.get('nick', '')).strip()
                key = nick.casefold()
                if not USERNAME_RE.fullmatch(nick) or key in seen:
                    continue
                seen.add(key)
                choices.append({
                    'archive_id': archive.id, 'nick': nick, 'name': str(item.get('name', '')),
                    'already_registered': key in existing,
                    'disqualified_in_source': bool(item.get('disqualified', False))
                })
        return {'available': True, 'editions': editions, 'players': choices,
                'registered_count': len(existing)}


@app.post('/api/admin/import-players')
def import_players(data: ImportPlayersIn, request: Request):
    """Copia inscrições autorizadas do arquivo para uma edição com inscrições abertas.

    Nicks repetidos, inclusive entre importação e inscrição pública concorrentes,
    são impedidos pela constraint UNIQUE de players.nick_key.
    """
    require_admin(request)
    with Session.begin() as db:
        t = db.get(Tournament, 1)
        if t.status != 'registration':
            fail(409, 'Só é possível transferir jogadores enquanto as inscrições estiverem abertas.')
        archive = db.get(TournamentArchive, data.archive_id)
        if archive is None:
            fail(404, 'Edição de origem não encontrada.')
        snapshot = json.loads(archive.snapshot)
        source = {str(item.get('nick', '')).strip().casefold(): item
                  for item in snapshot.get('players', []) if item.get('nick')}
        missing = [nick for nick in data.nicks if nick.casefold() not in source]
        if missing:
            fail(400, 'Alguns nicks selecionados não pertencem à edição de origem.')
        existing = {p.nick_key for p in db.scalars(select(Player)).all()}
        speed = speed_for_clock(t.minutes, t.increment)
        imported, skipped = [], []
        for nick in data.nicks:
            key = nick.casefold()
            if key in existing:
                skipped.append(nick)
                continue
            record = source[key]
            name = ' '.join(str(record.get('name', '')).split())
            canonical = str(record.get('nick', '')).strip()
            if not (2 <= len(name) <= 70 and USERNAME_RE.fullmatch(canonical)):
                skipped.append(nick)
                continue
            ratings = imported_ratings(record, snapshot.get('settings') or {})
            saved_manual = record.get('manual_ratings_json')
            try:
                saved_manual = json.loads(saved_manual) if isinstance(saved_manual, str) else (saved_manual or {})
            except (ValueError, TypeError):
                saved_manual = {}
            if not isinstance(saved_manual, dict):
                saved_manual = {}
            saved_manual = {k: v for k, v in saved_manual.items()
                            if k in SPEEDS and isinstance(v, int)
                            and not isinstance(v, bool) and 400 <= v <= 3500}
            chosen = ratings.get(speed) or {}
            rapid = ratings.get('rapid') or {}
            player = Player(
                name=name, nick=canonical, nick_key=canonical.casefold(),
                rating_reported=1500, rating_official=rapid.get('rating'),
                rating=saved_manual.get(speed) or chosen.get('rating') or 1500,
                provisional=0 if speed in saved_manual else int(bool(chosen.get('prov'))),
                verified=int(bool(ratings)),
                ratings_json=json.dumps(ratings, ensure_ascii=False) if ratings else None,
                manual_ratings_json=json.dumps(saved_manual) if saved_manual else None)
            db.add(player)
            existing.add(key)
            imported.append(canonical)
        try:
            db.flush()
        except IntegrityError:
            fail(409, 'Inscrição simultânea detectada. Atualize a lista e tente novamente.')
    return {'message': f'{len(imported)} jogador(es) transferido(s) para a edição atual.',
            'imported': len(imported), 'skipped': skipped}


@app.post('/api/admin/tournaments/new', status_code=201)
def create_next_tournament(data: NewTournamentIn, request: Request):
    require_admin(request)
    validate_settings(data)
    with Session.begin() as db:
        t = db.get(Tournament, 1)
        if t.status == 'active':
            fail(409, 'Conclua primeiro todas as rodadas do torneio atual.')
        previous = status_data(db, include_private=True)
        if t.status == 'registration' and previous['players']:
            fail(409, 'Há inscrições abertas. Para preservar os participantes, conclua a edição antes de criar outra.')
        if previous['players'] or previous['matches'] or t.status == 'finished':
            # Guarda uma cópia completa e imutável da edição anterior antes de limpar os dados ativos.
            db.add(TournamentArchive(title=t.title,
                                     snapshot=json.dumps(previous, ensure_ascii=False)))
        db.query(MatchGame).delete(synchronize_session=False)
        db.query(Match).delete(synchronize_session=False)
        db.query(Player).delete(synchronize_session=False)
        t.status = 'registration'
        t.current_round = 0
        t.round_started = None
        t.deadline = None
        t.champion_id = None
        update_settings(t, data)
    return {'message': 'Nova edição criada! A edição anterior foi preservada no histórico.'}


@app.post('/api/admin/start')
