.edition-bar{display:flex;justify-content:space-between;align-items:center;gap:20px;margin:19px 0 1px;padding:18px 23px;border:1px solid #e3e4df;border-radius:13px;background:#fff;flex-wrap:wrap}
.edition-bar>div{display:flex;flex-direction:column;gap:5px;min-width:210px}.edition-bar .mini-label{color:#ac864e;font-size:9px}
.edition-bar strong{font-size:15px;color:#263746}.edition-bar small{font-size:11px;color:#89949c}
.edition-bar select{min-width:260px;max-width:100%;font:inherit;font-size:12px;font-weight:700;padding:13px 16px;border:1px solid #d9e0de;background:#f8f9f6;border-radius:9px;color:#243645}
.admin-config{padding:25px;margin-bottom:22px;background:white;border:1px solid var(--border);border-radius:14px}
.admin-config-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;flex-wrap:wrap;margin-bottom:16px}
.admin-config-head h3{margin:0 0 6px;font-size:16px}.admin-config-head p{font-size:12px;color:#83909a;margin:0;line-height:1.65}
.settings-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.settings-field{display:flex;flex-direction:column;gap:7px}.settings-field.span-full{grid-column:1/-1}.settings-field.span-2{grid-column:span 2}
.settings-field label{font-weight:800;font-size:11px;color:#62717b}.settings-field input,.settings-field textarea{width:100%;border-radius:9px;border:1px solid #dce0dd;padding:12px 13px;background:#fcfcfa;color:#182a39;font:inherit;font-size:12px}
.settings-field textarea{min-height:80px;resize:vertical;line-height:1.6}.settings-field input:disabled{background:#f0f1ed;color:#8b959b}
.settings-actions{display:flex;align-items:center;flex-wrap:wrap;gap:14px;margin-top:18px}.settings-actions small{font-size:11px;color:#7e8c94;line-height:1.55;max-width:520px}
.admin-create-toggle{background:#f4f4ee;border:1px solid #e3e4db;padding:15px 20px;border-radius:12px;display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:22px}
.admin-create-toggle strong{font-size:13px}.admin-create-toggle small{font-size:11px;display:block;color:#82909a;margin-top:5px}
.admin-create-toggle button{border:1px solid #c6a473;color:#87602d;font-weight:800;border-radius:9px;padding:10px 14px;background:#fff;font-size:11px;white-space:nowrap}
.archive-banner{padding:14px 21px;background:#fff8ea;border:1px solid #f0dcb6;border-radius:10px;font-size:12px;color:#8a642e;margin-top:15px}
@media(max-width:700px){.settings-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.settings-field.span-2{grid-column:1/-1}.edition-bar select{width:100%}}
@media(max-width:430px){.settings-grid{grid-template-columns:1fr}.settings-field.span-2{grid-column:1/-1}}

.admin-export{margin:0 0 22px;padding:16px 20px;background:#eef2ef;border:1px solid #dae2dc;border-radius:12px;display:flex;gap:15px;align-items:center;justify-content:space-between;flex-wrap:wrap}.admin-export span{font-size:11px;line-height:1.6;color:#59706a}.admin-export .backup{background:#fff;border-color:#ced9d1;color:#44665b}.admin-export .backup:hover{background:#f6faf6}

/* Regulamento oficial por edição */
.regulation-paper{overflow:hidden;padding:0;background:#fff;border-radius:18px;border:1px solid #e1e4dd;box-shadow:0 12px 35px #14243608}
.regulation-header{padding:32px 36px;background:linear-gradient(125deg,#0d1a28,#223a4e);color:#fff}
.regulation-header h3{font-family:'Playfair Display',Georgia,serif;letter-spacing:-.025em;font-size:clamp(22px,2.6vw,32px);line-height:1.24;margin:12px 0}
.regulation-header>p{font-size:13px;line-height:1.75;margin:8px 0;color:#e0e5e7}
.regulation-header .regulation-info{color:#aebfc6;font-size:11px;margin-bottom:0}
.regulation-body{padding:10px 36px 34px;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);column-gap:42px}
.regulation-section{padding:23px 0;border-bottom:1px solid #ebeee8;break-inside:avoid}
.regulation-section h4{font-size:13px;line-height:1.4;letter-spacing:.06em;color:#233947;text-transform:uppercase;margin:0 0 14px}
.regulation-section ul{padding:0 0 0 18px;margin:0;list-style-type:disc}
.regulation-section li,.regulation-section p{color:#51616b;font-size:12px;line-height:1.8;margin:0 0 9px}
.regulation-section li::marker{color:var(--gold2)}
.regulation-editor{border-color:#e8d9b9}
.regulation-editor code{background:#f4eee4;border-radius:4px;padding:2px 4px;color:#886632}
.regulation-edit-row{border-top:1px solid #e9ebe6;padding:20px 0;display:grid;grid-template-columns:1fr;gap:9px}
.regulation-edit-row label{font-size:11px;font-weight:800;color:#5b6e79}
.regulation-edit-row input,.regulation-edit-row textarea{font:inherit;font-size:12px;line-height:1.65;color:#192e3e;padding:11px 13px;background:#fbfcfa;border:1px solid #dce3df;border-radius:9px;max-width:100%;width:100%}
.regulation-edit-row textarea{resize:vertical;min-height:110px}
.rules-alert{background:#fff7e6;color:#86612b!important;border:1px solid #ecd9ad;border-radius:8px;padding:12px}

/* Árvore de confronto, inspirada em chaves visuais de torneio */
.tree-intro{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:9px;padding:14px 16px;background:#eaf0ec;border:1px solid #d7e3dc;border-radius:11px;margin:16px 0 12px}
.tree-legend{font-size:11px;font-weight:600;color:#4e675e;line-height:1.6}.tree-legend i{display:inline-block;width:9px;height:9px;border-radius:50%;background:#4caf89;margin-right:5px}.tree-legend-dot{margin:0 6px}
.tree-scroller{max-width:100%;overflow-x:auto;overscroll-behavior-x:contain;scrollbar-color:#a58c63 #263b4b;scrollbar-width:thin;border-radius:18px;border:1px solid #34485a;padding:27px 22px 24px;background:radial-gradient(ellipse at 80% 10%,#273f4f 0,transparent 60%),linear-gradient(125deg,#101f2d,#172d40);box-shadow:0 18px 40px #0e223020}
.tournament-tree{display:flex;align-items:stretch;gap:48px;width:max-content;min-height:350px}
.tree-round{min-width:258px;width:258px;flex:0 0 258px;position:relative;display:flex;flex-direction:column;scroll-snap-align:start}
.tree-round-header{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:2px 0 14px;border-bottom:1px solid #ffffff25;color:#eac381}
.tree-round-header span{font-size:11px;letter-spacing:.14em;font-weight:800}.tree-round-header strong{font-size:10px;color:#acb9c1;white-space:nowrap;font-weight:600}
.tree-round-content{flex:1;display:flex;flex-direction:column;justify-content:space-around;gap:17px;padding:22px 0}
.tree-match{background:#fff;border-radius:12px;overflow:hidden;border:1px solid #d6e0dd;box-shadow:0 12px 16px #0819262b;position:relative}
.tree-match::after{content:"";position:absolute;right:0;top:50%;height:2px;width:8px;background:#bf975f}
.tree-match-head{padding:10px 11px;display:flex;justify-content:space-between;align-items:center;gap:6px;background:#f5f6f3;border-bottom:1px solid #e1e6e3;font-size:9px;color:#778792;letter-spacing:.08em;font-weight:800}
.tree-state{font-size:9px;letter-spacing:0;background:#ecefeb;color:#667b76;padding:4px 7px;border-radius:20px}
.tree-state.state-won{background:#e4f2e8;color:#267850}
.tree-player{border:0;border-bottom:1px solid #eff1ee;background:#fff;color:#1d3343;width:100%;display:flex;align-items:center;gap:9px;min-height:58px;text-align:left;padding:9px 11px;font-family:inherit;transition:background .16s}
button.tree-player:hover{background:#eff7f2}button.tree-player:focus-visible{outline:2px solid #70b593;outline-offset:-2px}
.tree-player-win{background:#ebf5eb;border-left:3px solid #3a9578;padding-left:8px}
.tree-player:last-child{border-bottom:0}
.tree-avatar{display:grid;place-items:center;flex:0 0 29px;width:29px;height:29px;background:#e8edf0;border:1px solid #d7e0e2;border-radius:50%;color:#355065;font-weight:800;font-size:12px}
.tree-player-win .tree-avatar{background:#d3e9db;color:#207250}
.tree-player-meta{min-width:0;flex:1;display:flex;flex-direction:column;gap:3px}
.tree-player-meta strong{font-size:11px;overflow-wrap:anywhere;line-height:1.25}
.tree-player-meta small{font-size:10px;color:#72848c;overflow-wrap:anywhere}
.tree-score{font-size:14px;font-weight:800;color:#1d7c66;min-width:24px;text-align:right}
.tree-player-empty .tree-avatar{background:#f1f1ee;color:#9ca9aa}
.tree-player-empty .tree-player-meta strong{font-weight:500;color:#95a0a3}
.tree-link{display:block;background:#f9f6ee;color:#926d30;padding:9px 12px;border-top:1px solid #ece1c8;font-weight:800;font-size:10px;line-height:1.4}
a.tree-link:hover{text-decoration:underline}
.tree-flow-arrow{color:#e3bb77;position:absolute;right:-33px;top:50%;font-size:25px;transform:translateY(-50%)}
.tree-final{min-width:270px;width:270px}
.tree-final .tree-round-header{color:#f5cb75}
.tree-trophy-box{display:flex;align-items:center;flex-direction:column;padding:18px 0 5px;gap:4px}
.tree-trophy{width:92px;height:100px;object-fit:contain;filter:drop-shadow(0 10px 12px #040c1380)}
.tree-trophy-box>span{font-weight:800;font-size:10px;color:#f0c77d;letter-spacing:.15em}
.tree-final .tree-round-content{justify-content:center}
.tree-mobile-tip{font-size:11px;line-height:1.8;color:#778b92;margin:12px 4px 4px}
.champion .tree-trophy{width:80px;height:80px;filter:drop-shadow(0 9px 6px #09132022)}

/* Histórico público individual */
body.modal-open{overflow:hidden}
.player-modal{position:fixed;inset:0;z-index:2000;display:grid;place-items:center;padding:18px}
.player-modal-backdrop{position:absolute;inset:0;background:#061523bd;backdrop-filter:blur(4px)}
.player-modal-panel{position:relative;width:min(620px,100%);max-height:min(85vh,800px);overflow-y:auto;background:#fff;border-radius:18px;padding:30px;border:1px solid #dce5df;box-shadow:0 30px 90px #0d1a289c}
.player-modal-close{position:absolute;right:16px;top:13px;line-height:1;width:34px;height:34px;border:1px solid #dce3e2;background:#f8faf7;border-radius:9px;color:#374d5a;font-size:24px}
#player-dialog-title{font-family:'Playfair Display',Georgia,serif;font-size:27px;color:#152a3a;margin:12px 25px 5px 0}
.player-dialog-info{font-size:12px;color:#778892;margin:0 0 18px}.player-dialog-info a{color:#207c70;font-weight:800}
.history-intro{border-radius:9px;padding:12px 14px;background:#f2f6f2;color:#55706b;font-size:11px;line-height:1.6}
.history-list{display:flex;flex-direction:column;gap:10px;margin-top:20px}
.history-row{display:flex;align-items:center;gap:13px;border:1px solid #e7ebe8;border-radius:11px;padding:12px}
.history-score{display:grid;place-items:center;background:#e8ecee;color:#46606e;border-radius:8px;min-width:38px;height:38px;font-weight:800;font-size:13px}
.history-win{color:#167253;background:#dff1e5}.history-loss{color:#93544e;background:#fff0ed}.history-draw{color:#84652e;background:#fff2d8}
.history-row-detail{flex:1;min-width:0}.history-row-detail strong{font-size:12px;line-height:1.4;display:block;color:#283e4b}.history-row-detail small{font-size:11px;color:#83909a;display:block;line-height:1.5;margin-top:3px;overflow-wrap:anywhere}
.history-open,.history-no-link{flex:0 0 auto;font-size:10px;color:#9a7339;font-weight:800;text-align:right}.history-no-link{color:#a8b0b4}
@media(max-width:800px){.regulation-body{grid-template-columns:1fr}.regulation-header{padding:26px 24px}.regulation-body{padding:7px 24px 25px}.tournament-tree{gap:34px}.tree-round{min-width:250px;width:250px;flex-basis:250px}.tree-flow-arrow{right:-26px}}
@media(max-width:600px){.tree-scroller{padding:17px 13px;scroll-snap-type:x proximity}.tournament-tree{gap:26px}.tree-round{min-width:min(270px,80vw);width:min(270px,80vw);flex-basis:min(270px,80vw)}.tree-flow-arrow{right:-23px}.tree-round-content{padding:15px 0}.tree-intro{padding:13px}.tree-legend{font-size:10px}.tree-trophy{width:75px;height:83px}.player-modal{padding:10px}.player-modal-panel{padding:20px 14px;max-height:92vh}.history-row{gap:8px;padding:9px}.history-open,.history-no-link{max-width:75px}.regulation-section{padding:19px 0}}

/* Chaves com peças e cores */
.tree-color-and-score{display:flex;align-items:flex-end;justify-content:center;flex-direction:column;gap:4px;min-width:58px}
.color-chip{font-size:9px;line-height:1.25;font-weight:800;white-space:nowrap;border-radius:5px;padding:3px 5px}
.white-piece{background:#f6f2e7;color:#5c533e;border:1px solid #d8d3c5}
.black-piece{background:#1b3043;color:#fff;border:1px solid #1b3043}
.unknown-piece{color:#9c8d73;background:#f4f0e7;font-size:8px;white-space:normal;max-width:75px;text-align:right}
.tree-player{min-height:65px}.tree-player-meta{max-width:125px}
@media(max-width:600px){.tree-player-meta{max-width:120px}.color-chip{font-size:9px}}
/* Classificação e troféus */
.ranking-note{display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:space-between;background:#e9f0ed;border:1px solid #d5e4dc;border-radius:12px;padding:15px 20px;color:#436458;margin-bottom:18px;font-size:12px}
.ranking-note strong{font-size:13px}
.ranking-podium{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:22px 0}
.podium-card{padding:24px 18px;background:white;border:1px solid #e0e4df;border-radius:16px;box-shadow:0 12px 28px #10202e0e;text-align:center;display:flex;flex-direction:column;gap:12px;min-width:0}
.podium-1{border-top:5px solid #d5a342;background:linear-gradient(180deg,#fff9e9,#fff 36%)}
.podium-2{border-top:5px solid #a0a9b7;background:linear-gradient(180deg,#f4f6f8,#fff 36%)}
.podium-3{border-top:5px solid #b67e52;background:linear-gradient(180deg,#fff4e9,#fff 36%)}
.podium-label{display:flex;flex-direction:column;align-items:center;gap:8px;font-size:11px;font-weight:900;color:#6c7580;letter-spacing:.13em}
.ranking-trophy{height:32px;width:32px;display:inline-block;vertical-align:middle;flex-shrink:0;filter:drop-shadow(0 3px 3px #0b19201f)}
.podium-label .ranking-trophy{height:65px;width:65px}
.ranking-trophy.gold{color:#d3a137}.ranking-trophy.silver{color:#a2aebc}.ranking-trophy.bronze{color:#bb8158}
.podium-name,.rank-player{border:0;background:transparent;text-align:center;cursor:pointer;color:#203442;font:inherit}
.podium-name strong,.podium-name small,.rank-player strong,.rank-player small{display:block;overflow-wrap:anywhere}
.podium-name strong{font-size:16px}.podium-name small,.rank-player small{font-size:11px;color:#73838c;margin-top:4px}
.podium-name:hover strong,.rank-player:hover strong{text-decoration:underline;color:#25765d}
.podium-stats{margin-top:auto;font-size:11px;line-height:1.5;color:#6e8084}
.ranking-panel{background:#fff;border-radius:16px;padding:24px;overflow:hidden}
.ranking-panel h3{font-size:18px;margin:0 0 16px}
.ranking-table-scroll{overflow-x:auto;max-width:100%;-webkit-overflow-scrolling:touch}
.ranking-table{border-collapse:collapse;width:100%;min-width:700px;font-size:12px;text-align:center}
.ranking-table th{background:#142838;color:#e7c083;font-size:10px;letter-spacing:.035em;padding:13px 10px;white-space:nowrap}
.ranking-table th:nth-child(2),.ranking-table td:nth-child(2){text-align:left}
.ranking-table td{padding:13px 10px;border-bottom:1px solid #e8ede9;white-space:nowrap}
.ranking-table tr:hover td{background:#f5f8f4}
.ranking-table td.rank-pos{width:52px}.ranking-table td.rank-pos svg{height:26px;width:26px}
.rank-player{text-align:left;min-width:120px}.rank-player strong{font-size:12px}
.rank-score{font-weight:900;color:#1f7961}
.ranking-criteria{font-size:11px;color:#73828d;line-height:1.75;margin:18px 0 0}
.ranking-empty{text-align:center;padding:45px 20px;background:white;border-radius:16px}
.ranking-empty h3{font-size:18px}.ranking-empty p{font-size:12px;color:#697b82}
@media(max-width:650px){.ranking-podium{gap:8px}.podium-card{padding:14px 7px;gap:9px}.podium-label{font-size:9px;letter-spacing:0}.podium-label .ranking-trophy{width:43px;height:43px}.podium-name strong{font-size:12px}.podium-name small,.podium-stats{font-size:10px}.ranking-panel{padding:14px}.ranking-note{padding:13px}}
@media(max-width:390px){.ranking-podium{grid-template-columns:1fr}.podium-card{flex-direction:row;text-align:left;align-items:center;gap:12px}.podium-label{flex:0 0 66px}.podium-name{text-align:left;flex:1}.podium-stats{max-width:90px;text-align:right}}


/* Reinscrição de jogadores de edições anteriores */
.import-player-panel,.disqualification-panel{margin-top:22px}
.import-player-panel .admin-config-head{padding-bottom:14px}
.import-source-label{font-size:12px;font-weight:800;color:#3b5061;display:block;margin:0 0 9px}
#import-source{width:100%;background:#fff;border:1px solid #d8dfdb;border-radius:10px;padding:12px 14px;font-size:13px;color:#223b4a}
#import-form{padding:12px 22px 20px}
.import-selection-toolbar{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;align-items:center;border-bottom:1px solid #e2e7e3;padding:16px 0;font-size:12px;color:#667b7e}
.import-selection-toolbar div{display:flex;gap:12px}
.import-selection-toolbar button{border:none;background:transparent;color:#8e6e38;text-decoration:underline;text-underline-offset:3px;cursor:pointer;font:inherit;font-size:12px}
.import-list{max-height:330px;overflow:auto;border:1px solid #e6eae5;border-radius:10px;margin:14px 0;background:#fff}
.import-person{display:flex;align-items:center;gap:12px;padding:12px 14px;border-bottom:1px solid #edf0ec;cursor:pointer;min-width:0}
.import-person:last-child{border-bottom:0}.import-person:hover{background:#f6f8f5}
.import-person input{accent-color:#3b876e;flex-shrink:0;width:17px;height:17px}
.import-person-details{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}
.import-person-details strong{font-size:12px;overflow-wrap:anywhere}
.import-person-details small{font-size:11px;color:#76888c;overflow-wrap:anywhere}
.import-person-status{font-size:10px;color:#487864;white-space:nowrap}
.import-existing{cursor:default;opacity:.57;background:#f8f9f7}
.import-existing:hover{background:#f8f9f7}
.import-existing .import-person-status{color:#77848a}
#import-form .settings-actions{margin-top:13px}
#import-form .settings-actions small{line-height:1.6}
.disqualification-head{padding:22px 22px 10px}
.disqualification-head h3{font-size:18px;margin:0 0 8px}
.disqualification-head p,.disqualification-form p{font-size:12px;line-height:1.7;color:#657b83}
.disqualification-players{padding:0 22px 18px}
.disqualification-person{display:flex;justify-content:space-between;align-items:center;gap:12px;border-top:1px solid #e6eae6;padding:13px 0}
.disqualification-person span{min-width:0;display:flex;flex-direction:column;gap:4px}
.disqualification-person strong{font-size:12px}
.disqualification-person small{font-size:11px;color:#85929c;overflow-wrap:anywhere}
.disqualify-btn{border:1px solid #d9b5a7;background:#fff7f5;color:#95483e;border-radius:8px;cursor:pointer;padding:10px 12px;font-size:11px;font-weight:800;white-space:nowrap}
.disqualify-btn:hover{background:#ffede8}
#disqualification-form-area:empty{display:none}
.disqualification-form{margin:0 22px 22px!important;border:1px solid #e8d6c9;border-radius:11px;padding:18px}
.disqualification-form h4{margin:0 0 10px}
.disqualification-form textarea{width:100%;min-height:95px;resize:vertical;border:1px solid #dce4e0;border-radius:8px;padding:10px;color:#233b49;font:inherit;font-size:12px}
.disqualification-actions{display:flex;gap:10px;flex-wrap:wrap;padding-top:12px}
.disqualification-history{margin:12px 22px 22px;border-top:1px solid #e4e9e5;padding-top:15px}
.disqualification-history h4{margin:0 0 12px;color:#415a65}
.disqualification-record{padding:11px 0;border-bottom:1px solid #e8ece8;display:grid;gap:5px;font-size:12px}
.disqualification-record span{font-size:11px;color:#788b91}
.disqualification-record p{margin:0;font-size:11px;color:#596e75;overflow-wrap:anywhere}
.tree-player-disqualified{opacity:.72;background:#fff8f5}
.tree-player-disqualified .tree-player-meta strong{text-decoration:line-through;text-decoration-thickness:1px}
.ranking-disqualified{background:#f9f4f2;color:#866961}
.ranking-disqualified .rank-player small{color:#ab6b56}
@media(max-width:600px){
 #import-form,.disqualification-players{padding-left:14px;padding-right:14px}
 .disqualification-head{padding:20px 14px 8px}
 .import-person{padding:12px 9px;gap:8px}
 .import-selection-toolbar{align-items:flex-start}
 .disqualification-form{margin:0 12px 15px!important}
 .disqualification-history{margin-left:14px;margin-right:14px}
 .import-person-status{font-size:9px}
